import { useState } from 'react';
import { Button } from '@jinx-ui/react';

interface ContactsData {
  fullName: string;
  email: string;
  phone: string;
}

interface AddressData {
  street: string;
  city: string;
  zip: string;
}

export interface RegistrationData {
  contacts: ContactsData;
  address: AddressData;
}

interface RegistrationFormProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [contacts, setContacts] = useState<ContactsData>({
    fullName: '',
    email: '',
    phone: '',
  });
  const [address, setAddress] = useState<AddressData>({
    street: '',
    city: '',
    zip: '',
  });

  const isLastStep = step === STEPS.length - 1;
  const isFirstStep = step === 0;

  const handleNext = () => {
    if (!isLastStep) {
      setStep((current) => current + 1);
    }
  };

  const handleBack = () => {
    if (!isFirstStep) {
      setStep((current) => current - 1);
    }
  };

  const handleSubmit = () => {
    onSubmit({ contacts, address });
  };

  return (
    <div className="jx-card jx-stack" style={{ gap: 'var(--jx-space-lg)' }}>
      <ol className="jx-stepper" aria-label="Шаги регистрации">
        {STEPS.map((label, index) => {
          const status =
            index === step ? 'active' : index < step ? 'done' : 'upcoming';
          return (
            <li
              key={label}
              className={`jx-step jx-step--${status}`}
              aria-current={index === step ? 'step' : undefined}
            >
              <span className="jx-step__index">{index + 1}</span>
              <span className="jx-step__label">{label}</span>
            </li>
          );
        })}
      </ol>

      {step === 0 && (
        <fieldset className="jx-fieldset jx-stack" style={{ gap: 'var(--jx-space-md)' }}>
          <legend className="jx-legend">Контакты</legend>

          <div className="jx-field">
            <label className="jx-label" htmlFor="fullName">
              Имя и фамилия
            </label>
            <input
              id="fullName"
              className="jx-input"
              type="text"
              value={contacts.fullName}
              onChange={(event) =>
                setContacts((prev) => ({ ...prev, fullName: event.target.value }))
              }
            />
          </div>

          <div className="jx-field">
            <label className="jx-label" htmlFor="email">
              Email
            </label>
            <input
              id="email"
              className="jx-input"
              type="email"
              value={contacts.email}
              onChange={(event) =>
                setContacts((prev) => ({ ...prev, email: event.target.value }))
              }
            />
          </div>

          <div className="jx-field">
            <label className="jx-label" htmlFor="phone">
              Телефон
            </label>
            <input
              id="phone"
              className="jx-input"
              type="tel"
              value={contacts.phone}
              onChange={(event) =>
                setContacts((prev) => ({ ...prev, phone: event.target.value }))
              }
            />
          </div>
        </fieldset>
      )}

      {step === 1 && (
        <fieldset className="jx-fieldset jx-stack" style={{ gap: 'var(--jx-space-md)' }}>
          <legend className="jx-legend">Адрес</legend>

          <div className="jx-field">
            <label className="jx-label" htmlFor="street">
              Улица и дом
            </label>
            <input
              id="street"
              className="jx-input"
              type="text"
              value={address.street}
              onChange={(event) =>
                setAddress((prev) => ({ ...prev, street: event.target.value }))
              }
            />
          </div>

          <div className="jx-field">
            <label className="jx-label" htmlFor="city">
              Город
            </label>
            <input
              id="city"
              className="jx-input"
              type="text"
              value={address.city}
              onChange={(event) =>
                setAddress((prev) => ({ ...prev, city: event.target.value }))
              }
            />
          </div>

          <div className="jx-field">
            <label className="jx-label" htmlFor="zip">
              Индекс
            </label>
            <input
              id="zip"
              className="jx-input"
              type="text"
              value={address.zip}
              onChange={(event) =>
                setAddress((prev) => ({ ...prev, zip: event.target.value }))
              }
            />
          </div>
        </fieldset>
      )}

      {step === 2 && (
        <div className="jx-stack" style={{ gap: 'var(--jx-space-md)' }}>
          <h3 className="jx-heading">Проверка данных</h3>

          <dl className="jx-summary">
            <dt className="jx-summary__term">Имя и фамилия</dt>
            <dd className="jx-summary__value">{contacts.fullName || '—'}</dd>

            <dt className="jx-summary__term">Email</dt>
            <dd className="jx-summary__value">{contacts.email || '—'}</dd>

            <dt className="jx-summary__term">Телефон</dt>
            <dd className="jx-summary__value">{contacts.phone || '—'}</dd>

            <dt className="jx-summary__term">Улица и дом</dt>
            <dd className="jx-summary__value">{address.street || '—'}</dd>

            <dt className="jx-summary__term">Город</dt>
            <dd className="jx-summary__value">{address.city || '—'}</dd>

            <dt className="jx-summary__term">Индекс</dt>
            <dd className="jx-summary__value">{address.zip || '—'}</dd>
          </dl>
        </div>
      )}

      <div className="jx-row" style={{ justifyContent: 'space-between' }}>
        <Button variant="secondary" onClick={handleBack} disabled={isFirstStep}>
          Назад
        </Button>

        {isLastStep ? (
          <Button variant="primary" onClick={handleSubmit}>
            Отправить
          </Button>
        ) : (
          <Button variant="primary" onClick={handleNext}>
            Дальше
          </Button>
        )}
      </div>
    </div>
  );
}

